def parse_demo_text(t):
    sections={}
    pat=re.compile(r'Demo pair \d+ (input|output) \((\d+)x(\d+)\):\n')
    matches=list(pat.finditer(t))
    for ix,m in enumerate(matches):
        end=matches[ix+1].start() if ix+1<len(matches) else len(t)
        block=t[m.end():end]
        h,w=map(int,m.group(2,3))
        rows=[[int(x) for x in ln.split()] for ln in block.strip().splitlines()[:h]]
        assert len(rows)==h and all(len(row)==w for row in rows), (m.group(1),h,w,[len(row) for row in rows])
        sections[m.group(1)]=rows
    return sections
